import 'package:drift/drift.dart';

/// The possible lifecycle states of a task.
enum TaskStatus {
  /// The task has not been completed yet.
  pending,

  /// The task has been marked as completed.
  completed,
}

/// The relative importance of a task.
enum TaskPriority {
  low,
  medium,
  high,
}

/// The `tasks` table.
///
/// Each row is a single task owned by the local device. Identifiers are
/// generated by the application (see the `uuid` package) before insertion,
/// so the database never has to allocate them.
class Tasks extends Table {
  /// Locally generated stable identifier (UUID v4).
  TextColumn get id => text()();

  /// Required, non-empty task title.
  TextColumn get title => text()();

  /// Optional free-form description.
  TextColumn get description => text().nullable()();

  /// Lifecycle state of the task.
  TextColumn get status => text()
      .map(const EnumNameConverter<TaskStatus>(TaskStatus.values))
      .withDefault(Constant(TaskStatus.pending.name))();

  /// Relative importance of the task.
  TextColumn get priority => text()
      .map(const EnumNameConverter<TaskPriority>(TaskPriority.values))
      .withDefault(Constant(TaskPriority.medium.name))();

  /// Optional local deadline for the task.
  DateTimeColumn get dueDate => dateTime().nullable()();

  /// When the task was first created.
  DateTimeColumn get createdAt => dateTime()();

  /// When the task was last modified.
  DateTimeColumn get updatedAt => dateTime()();

  /// When the task was marked as completed, if ever.
  DateTimeColumn get completedAt => dateTime().nullable()();

  @override
  Set<Column> get primaryKey => {id};
}
